select
u.user_id,u.username,u.real_name,u.phone,u.email,u.avatar,u.role,u.status,u.last_login
from users u
join volunteer_info v on u.user_id = v.user_id


        AND v.status = #{status}


        AND v.grade = #{grade}


        AND v.major_class like "%"#{majorClass}"%"


        AND u.user_id != #{excludeUserId}

select * from user_follow uf
uf.follower_id = #{userId}
AND uf.status = #{status}
AND EXISTS (select 1 from users u where u.user_id = uf.followee_id and u.username like CONCAT('%', #{keyword}, '%'))

select * from user_follow uf
uf.followee_id = #{userId}
AND uf.status = #{status}
AND EXISTS (select 1 from users u where u.user_id = uf.followee_id and u.username like CONCAT('%', #{keyword}, '%'))

mapper.update:
update user_follow


        status = #{status},



    follower_id = #{followerId} and followee_id = #{followeeId}
